-- Schema only. Performance indexes and partitions intentionally live in database-labs.
CREATE TABLE operations_incident (id BIGSERIAL PRIMARY KEY, incident_key VARCHAR(128) NOT NULL UNIQUE, incident_type VARCHAR(64) NOT NULL, source_service VARCHAR(128) NOT NULL, recovery_target VARCHAR(128) NOT NULL, aggregate_id VARCHAR(128) NULL, status VARCHAR(32) NOT NULL, severity VARCHAR(16) NOT NULL, last_error TEXT NULL, last_recovery_message TEXT NULL, first_seen_at TIMESTAMP NOT NULL, last_seen_at TIMESTAMP NOT NULL, resolved_at TIMESTAMP NULL);
CREATE TABLE recovery_attempt (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES operations_incident(id), requested_by VARCHAR(128) NOT NULL, action VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, message TEXT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE inbox_event (id BIGSERIAL PRIMARY KEY, consumer_name VARCHAR(128) NOT NULL, event_id VARCHAR(36) NOT NULL, processed_at TIMESTAMP NOT NULL, UNIQUE(consumer_name,event_id));
CREATE TABLE outbox_event (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(36) NOT NULL UNIQUE, aggregate_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, payload_json JSONB NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL, processed_at TIMESTAMP NULL);
